    def catalan_number(n):
        if n <= 1:
            return 1
        res_num = 1
        res_den = 1
        for i in range(2, n + 1):
            res_num *= (n + i)
            res_den *= i
        return res_num // res_den % MOD

    def count_ways_to_place_s(n, s):
        m = len(s)
        dp = [[0] * (m + 1) for _ in range(n + 1)]
        dp[0][0] = 1

        for i in range(1, n + 1):
            dp[i][0] = dp[i - 1][0]
            for j in range(1, m + 1):
                if s[j - 1] == '(':
                    dp[i][j] = (dp[i - 1][j] + dp[i - 1][j - 1]) % MOD
                else:
                    if j > 1 and s[j - 2] == '(':
                        dp[i][j] = (dp[i - 1][j] + dp[i - 1][j - 2]) % MOD

        return dp[n][m]

    total_sequences = 0
    for i in range(len(s), 2 * n - len(s) + 1):
        left = catalan_number(i)
        right = catalan_number(2 * n - i - len(s))
        total_sequences = (total_sequences + left * right * count_ways_to_place_s(i, s)) % MOD

    return total_sequences

