def count_sequences(n, s):
    def catalan(n):
        if n == 0:
            return 1
        res_num = 1
        for i in range(2, n + 1):
            res_num *= (n + i)
            res_num //= i
        return res_num % MOD

    def count_ways(left, right, open_count, memo):
        if (left, right, open_count) in memo:
            return memo[(left, right, open_count)]

        if left > len(s) or right < 0 or open_count < 0:
            return 0

        if left == len(s) and right == -1 and open_count == 0:
            return 1

        ways = 0
        if left <= len(s) and s[left] == '(':
            ways += count_ways(left + 1, right, open_count + 1, memo)
        if right >= 0 and s[right] == ')':
            ways += count_ways(left, right - 1, open_count - 1, memo)

        memo[(left, right, open_count)] = ways % MOD
        return memo[(left, right, open_count)]

    total_ways = 0
    for i in range(len(s)):
        if s[i] == '(':
            total_ways += (catalan(i) * catalan(len(s) - i - 1)) % MOD
            total_ways %= MOD

    memo = {}
    total_ways += count_ways(0, len(s) - 1, 0, memo)
    total_ways %= MOD

    return total_ways

